sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {
        var util = new UtilAIAB();

        var prompt = current.getValue('u_prompt');
        var table = current.getValue('u_table');
        var target = current.getValue('u_target');
        var type = current.getValue('u_type');
        var model = current.getValue('u_model') || gs.getProperty('ai_in_a_box.config.server.llm.model');
        var requestingUserId = current.getValue('u_requested_by') || current.getValue('sys_created_by');

        // Resolve user ID if needed
        if (!requestingUserId) {
            var userGR = new GlideRecord('sys_user');
            userGR.addQuery('user_name', current.getValue('sys_created_by'));
            userGR.setLimit(1);
            userGR.query();
            if (userGR.next()) {
                requestingUserId = userGR.getUniqueValue();
            }
        }

        // Build messages based on type
        var messages;
        if (type == 'summarize-simple') {
            messages = util.buildTableMessages(current, table, target, requestingUserId);
        } else if (type == 'chat' || type == 'generic') {
            messages = util.setPromptToJSON(prompt);
        } else {
            messages = util.setPromptToJSON(prompt || 'No prompt provided');
        }

        // Ensure session exists for tracking
        var sessionId = util.getOrCreateSession(current, requestingUserId);

        // Get tools with dynamic skill list
        var tools = util.getActiveTools(current);

        // Update and send to server
        current.u_prompt = JSON.stringify(messages, null, ' ');
        current.u_state = 'requested';
        current.update();

        gs.info('AIAB: Sending inference ' + current.getValue('sys_id') + 
                ' (session: ' + sessionId + ') for user ' + requestingUserId + 
                ' with ' + tools.length + ' tools');

        // Send to server - it handles everything asynchronously
        var aiabRest = new global.RestAIAB();
        var restMessageNoTable = aiabRest.send({
            body: {
                messages: messages,
                model: model,
                tools: tools.length > 0 ? tools : undefined
            },
            path: "/openai/v1/chat/completions",
            method: "post",
            headers: {
                "ai_in_a_box.inference.id": current.getValue('sys_id'),
                "ai_in_a_box.user.id": requestingUserId
            }
        });

        if (!restMessageNoTable) {
            current.u_response = 'Error: No response from AI in a Box server';
            current.u_state = 'finished';
            current.update();
        }
        // Server handles the rest via streaming callbacks - DO NOT parse response here

    } catch (error) {
        gs.error('AIAB: Error in Fetch Inference business rule: ' + error);
        current.u_response = 'Error: ' + (error.message || String(error));
        current.u_state = 'finished';
        current.update();
    }
})(current, previous);
